+  const file = join(dir, relPath);
+  mkdirSync(dirname(file), { recursive: true });
+  writeFileSync(file, content);
+  execFileSync("git", ["add", relPath], { cwd: dir, shell: false });
+  execFileSync("git", ["commit", "-q", "-m", "init"], { cwd: dir, shell: false });
+}
